-- A unique violation in a buffered COPY is found when its multi-insert buffer is flushed
-- (1,000 rows or 64 kB of lines): the defaults of the buffer's later rows are evaluated first.
CREATE TABLE a148_cb (id int PRIMARY KEY, a int, b text, s serial);
SELECT nextval('a148_cb_s_seq');
SELECT nextval('a148_cb_s_seq');
SELECT nextval('a148_cb_s_seq');
SELECT nextval('a148_cb_s_seq');
SELECT nextval('a148_cb_s_seq');
SELECT nextval('a148_cb_s_seq');
SELECT count(*) FROM a148_cb;
-- With a BEFORE ROW trigger rows go in one at a time: found at once.
CREATE FUNCTION a148_cb_t() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
CREATE TRIGGER a148_cb_t BEFORE INSERT ON a148_cb FOR EACH ROW EXECUTE FUNCTION a148_cb_t();
SELECT nextval('a148_cb_s_seq');
DROP TABLE a148_cb;
DROP FUNCTION a148_cb_t();
